'use client'
import {useRef,useState} from 'react'
import {useRouter} from 'next/navigation'
import {manageStore,messageStore} from '@/lib/vendor/store-management'
type State={owner_paused:boolean;admin_paused:boolean;admin_closed:boolean;closed:boolean;cleanup_pending:number}
export default function StoreControls({sellerId,state,admin=false}:{sellerId:string;state:State;admin?:boolean}){
  const router=useRouter(),dialog=useRef<HTMLDialogElement>(null)
  const [action,setAction]=useState(''),[note,setNote]=useState(''),[confirmation,setConfirmation]=useState(''),[busy,setBusy]=useState(false),[notice,setNotice]=useState('')
  const paused=admin?state.admin_paused:state.owner_paused
  const labels:Record<string,string>={pause:'Pause listings',resume:'Resume listings',close:'Close store',reopen:'Reopen store',purge_images:'Permanently remove public photos',retry_cleanup:'Retry photo cleanup'}
  function open(value:string){setAction(value);setNote('');setConfirmation('');setNotice('');dialog.current?.showModal()}
  async function submit(){setBusy(true);try{const result=await manageStore({sellerId,action,note});if('error'in result){setNotice(result.error);return}dialog.current?.close();setNotice(result.pending?`Store updated. ${result.pending} photos remain queued; retry cleanup to continue.`:'Store updated successfully.');router.refresh()}catch{setNotice('Could not confirm the result. Refresh before retrying.')}finally{setBusy(false)}}
  async function message(){setBusy(true);try{const result=await messageStore(sellerId);if('error'in result)setNotice(result.error);else router.push('/messages/'+result.id)}catch{setNotice('Could not open messages.')}finally{setBusy(false)}}
  return <section className="buyer-panel buyer-stack"><h2>Store controls</h2><p>{state.closed?'Store closed.':state.owner_paused||state.admin_paused?'Listings paused.':'Store open.'} {state.admin_paused&&'Admin pause is active.'} {state.admin_closed&&'Admin closure is active.'}</p><p className="buyer-help">Pausing hides published items and blocks new purchases. Existing orders and messages remain available. Resuming restores only listings hidden by the pause, when no other pause or closure remains.</p><div className="buyer-actions">{!state.closed&&<button className="buyer-btn" onClick={()=>open(paused?'resume':'pause')}>{labels[paused?'resume':'pause']}</button>}<button className="buyer-btn" disabled={!admin&&state.admin_closed} onClick={()=>open(state.closed?'reopen':'close')}>{labels[state.closed?'reopen':'close']}</button>{state.closed&&<button className="buyer-btn is-danger" onClick={()=>open('purge_images')}>Remove public photos permanently</button>}{state.closed&&state.cleanup_pending>0&&<button className="buyer-btn" onClick={()=>open('retry_cleanup')}>Retry photo cleanup ({state.cleanup_pending})</button>}{admin&&<button className="buyer-btn" disabled={busy} onClick={()=>void message()}>Message vendor</button>}</div>{notice&&<p role="status" className="buyer-notice">{notice}</p>}
  <dialog ref={dialog} className="by-cancel-dialog" onCancel={e=>{if(busy)e.preventDefault()}} aria-labelledby="store-control-title"><h2 id="store-control-title">{labels[action]}</h2><p>{action==='purge_images'?'This permanently removes public listing photos and the store logo, including unused uploads. It cannot be undone. Close the store and settle existing orders and finances first. Order records and private verification documents are retained.':action==='close'?'This hides all published listings. Your buyer account and existing order responsibilities remain. Reopening keeps listings as drafts for review.':'Record why you are changing the store. Another active pause or admin closure may still prevent publishing.'}</p><label className="buyer-form">Reason<textarea className="buyer-input" value={note} onChange={e=>setNote(e.target.value)} maxLength={1000} rows={3}/></label>{action==='purge_images'&&<label className="buyer-form">Type DELETE PHOTOS to confirm<input className="buyer-input" value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label>}<div className="buyer-actions"><button className="buyer-btn is-primary" disabled={busy||note.trim().length<5||(action==='purge_images'&&confirmation!=='DELETE PHOTOS')} onClick={()=>void submit()}>{busy?'Working…':'Confirm'}</button><button className="buyer-btn" disabled={busy} onClick={()=>dialog.current?.close()}>Cancel</button></div>{notice&&<p role="alert">{notice}</p>}</dialog></section>
}
